// Files that make the dataset and the site discoverable, all generated by the site build from existing files:
//   dataFiles()  the Croissant (mlcommons) metadata of the CSV exports, and a machine-readable index of the export (data/export/index.json in the built site)
//   siteFiles()  sitemap.xml, robots.txt and an Atom feed generated from CHANGELOG.md
//   datasetLd()  the schema.org Dataset description (JSON-LD) of the data page
// Nothing here is typed that a saved file could change; nothing makes a request when a page loads.
import { createHash } from "node:crypto";

const esc = s => String(s ?? "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&apos;" }[c]));
const sha256 = t => createHash("sha256").update(t).digest("hex");
const bytesOf = t => Buffer.byteLength(t, "utf8");
const MIME = { ".csv": "text/csv", ".json": "application/json", ".bib": "application/x-bibtex", ".py": "text/x-python" };
const mime = f => MIME[f.slice(f.lastIndexOf("."))] || "application/octet-stream";

// authors of CITATION.cff (the block "authors:"; family-names, given-names, optional orcid); no e-mail address is published in the metadata
export function parseCff(text) {
  const block = (text.match(/^authors:\s*\n((?:[ \t]+.*\n?)+)/m) || [])[1] || "";
  return block.split(/^\s*-\s+/m).filter(Boolean).map(b => {
    const g = k => (b.match(new RegExp(`${k}:\\s*"?([^"\\n]+)"?`)) || [])[1]?.trim();
    return { family: g("family-names"), given: g("given-names"), orcid: g("orcid") };
  }).filter(a => a.family);
}

// RFC 4180 parser; lines that start with # before the header are comments (the export files begin with two)
export function parseCsv(text) {
  const rows = []; let row = [], f = "", q = false, i = 0;
  const lines = [];
  while (text.startsWith("#")) { const e = text.indexOf("\n"); lines.push(text.slice(0, e)); text = text.slice(e + 1); }
  for (; i < text.length; i++) {
    const c = text[i];
    if (q) { if (c === '"') { if (text[i + 1] === '"') { f += '"'; i++; } else q = false; } else f += c; }
    else if (c === '"') q = true;
    else if (c === ",") { row.push(f); f = ""; }
    else if (c === "\n" || c === "\r") { if (c === "\r" && text[i + 1] === "\n") i++; row.push(f); f = ""; if (row.length > 1 || row[0] !== "") rows.push(row); row = []; }
    else f += c;
  }
  if (f !== "" || row.length) { row.push(f); rows.push(row); }
  return { comments: lines, header: rows[0], rows: rows.slice(1) };
}

// Croissant data type of a column, read from its values: Boolean, Integer, Float, Date or Text
function dataType(values) {
  const v = values.filter(x => x !== "");
  if (!v.length) return "sc:Text";
  if (v.every(x => x === "true" || x === "false")) return "sc:Boolean";
  if (v.every(x => /^-?\d+$/.test(x))) return "sc:Integer";
  if (v.every(x => /^-?(\d+\.?\d*|\.\d+)([eE][-+]?\d+)?$/.test(x))) return "sc:Float";
  if (v.every(x => /^\d{4}-\d{2}-\d{2}$/.test(x))) return "sc:Date";
  return "sc:Text";
}

const CONTEXT = { "@language": "en", "@vocab": "https://schema.org/", citeAs: "cr:citeAs", column: "cr:column", conformsTo: "dct:conformsTo", cr: "http://mlcommons.org/croissant/", rai: "http://mlcommons.org/croissant/RAI/", examples: { "@id": "cr:examples", "@type": "@json" }, data: { "@id": "cr:data", "@type": "@json" }, dataType: { "@id": "cr:dataType", "@type": "@vocab" }, dct: "http://purl.org/dc/terms/", equivalentProperty: "cr:equivalentProperty", extract: "cr:extract", field: "cr:field", fileProperty: "cr:fileProperty", fileObject: "cr:fileObject", fileSet: "cr:fileSet", format: "cr:format", includes: "cr:includes", isLiveDataset: "cr:isLiveDataset", jsonPath: "cr:jsonPath", key: "cr:key", md5: "cr:md5", parentField: "cr:parentField", path: "cr:path", recordSet: "cr:recordSet", references: "cr:references", regex: "cr:regex", repeated: "cr:repeated", replace: "cr:replace", samplingRate: "cr:samplingRate", sc: "https://schema.org/", separator: "cr:separator", source: "cr:source", subField: "cr:subField", transform: "cr:transform" };
const RECORDSETS = {
  "sim-highline-records.csv": ["records", "One row per evidence record (a curve, a fit or a distribution): source, run, relation, epoch, evidence tier, rankable flag, definitions, citation, DOI and checksum."],
  "sim-highline-points.csv": ["points", "One row per plotted point of a record, keyed by record_id; parametric records are sampled at the number of points the manifest states."],
  "sim-highline-distributions.csv": ["distributions", "One row per non-empty cell of the per-galaxy distributions of a record, keyed by record_id."]
};

export function dataFiles({ release, manifest, cov, notes, cff, SITE_URL, texts, fileInfo, keywords, description }) {
  const authors = parseCff(cff), creator = authors.map(a => ({ "@type": "Person", name: `${a.given} ${a.family}`.trim(), ...(a.orcid ? { identifier: a.orcid } : {}) }));
  const url = f => `${SITE_URL}/data/export/${f}`;
  const csvs = Object.keys(RECORDSETS).filter(f => manifest.files[f] && texts[f] != null);
  const distribution = [], recordSet = [], rowCounts = {}, commentLines = {};
  for (const f of csvs) {
    const m = manifest.files[f], P = parseCsv(texts[f]), [rs, about] = RECORDSETS[f];
    rowCounts[f] = P.rows.length; commentLines[f] = P.comments.length;
    distribution.push({ "@type": "cr:FileObject", "@id": f, name: f, description: fileInfo[f] || about, contentUrl: url(f), encodingFormat: "text/csv", sha256: m.sha256, contentSize: `${m.bytes} B` });
    const cols = manifest.columns[rs] || P.header;
    if (cols.join() !== P.header.join()) throw new Error(`${f}: header differs from the columns in the manifest`);
    recordSet.push({ "@type": "cr:RecordSet", "@id": rs, name: rs, description: about, ...(P.header[0] === "record_id" && rs === "records" ? { key: { "@id": `${rs}/record_id` } } : {}),
      field: P.header.map((c, j) => ({ "@type": "cr:Field", "@id": `${rs}/${c}`, name: c, description: `Column ${c} of ${f}.`, dataType: dataType(P.rows.map(r => r[j] ?? "")), source: { fileObject: { "@id": f }, extract: { column: c } } })) });
  }
  const license = "https://creativecommons.org/licenses/by/4.0/";
  const croissant = {
    "@context": CONTEXT, "@type": "sc:Dataset", conformsTo: "http://mlcommons.org/croissant/1.0", name: release.title, description: `${description} The CSV files begin with comment lines that start with "#" (${Object.entries(commentLines).map(([f, n]) => `${RECORDSETS[f][0]}: ${n}`).join(", ")}); skip them when reading a table.`, url: `${SITE_URL}/site/data.html`, version: release.version, datePublished: release.released,
    license, identifier: `https://doi.org/${release.doi}`, sameAs: `https://doi.org/${release.doi}`, citeAs: `Bhatia, S. (${release.released.slice(0, 4)}). ${release.title} (v${release.version}). Zenodo. https://doi.org/${release.doi}`,
    creator, keywords, isBasedOn: release.repo, distribution, recordSet
  };
  const croissantText = JSON.stringify(croissant, null, 2) + "\n";
  const files = Object.entries(manifest.files).map(([name, m]) => ({ name, url: url(name), path: `data/export/${name}`, mediaType: mime(name), bytes: m.bytes, sha256: m.sha256, description: fileInfo[name] || "", ...(rowCounts[name] != null ? { rows: rowCounts[name], commentLinesBeforeHeader: commentLines[name], columns: manifest.columns[RECORDSETS[name][0]] } : {}) }));
  const relations = Object.entries(cov.byRelation).map(([code, v]) => ({ code, title: notes[code]?.title || null, records: v.records, rankable: v.rankable, epochs: v.epochs.length ? [Math.min(...v.epochs), Math.max(...v.epochs)] : null, explorer: `${SITE_URL}/highline.html#r=${code}` })).sort((a, b) => b.records - a.records || a.code.localeCompare(b.code));
  const out = { croissant: { name: "sim-highline-croissant.json", text: croissantText }, creator, relations, rowCounts };
  const index = {
    schema: "sim-highline export index, version 1", name: release.title, version: release.version, released: release.released, doi: release.doi, doiUrl: `https://doi.org/${release.doi}`, license: release.license, creator: creator.map(c => c.name), homepage: `${SITE_URL}/site/data.html`, repository: release.repo,
    counts: { records: manifest.nRecords, points: manifest.nPoints, distributionRecords: manifest.nDistributionRecords, distributionCells: manifest.nDistributionCells, relations: cov.totals.relations, sources: cov.totals.sources },
    files: [...files, { name: out.croissant.name, url: url(out.croissant.name), path: `data/export/${out.croissant.name}`, mediaType: "application/ld+json", bytes: bytesOf(croissantText), sha256: sha256(croissantText), description: "Croissant (mlcommons) metadata of the three CSV files: file checksums, record sets and typed fields." }],
    discovery: { dataPage: `${SITE_URL}/site/data.html`, sitemap: `${SITE_URL}/sitemap.xml`, feed: `${SITE_URL}/feed.xml`, croissant: url(out.croissant.name) },
    relations
  };
  out.index = { name: "index.json", text: JSON.stringify(index, null, 2) + "\n" };
  out.indexMeta = { sha256: sha256(out.index.text), bytes: bytesOf(out.index.text) };
  out.croissantMeta = { sha256: sha256(croissantText), bytes: bytesOf(croissantText) };
  return out;
}

// schema.org Dataset (JSON-LD): the fields dataset search reads, with the relations as variableMeasured and the machine-readable files as distributions
export function datasetLd({ release, manifest, SITE_URL, description, keywords, creator, relations, croissant, croissantMeta, indexMeta, fileInfo }) {
  const dl = (name, m, type) => ({ "@type": "DataDownload", name, contentUrl: `${SITE_URL}/data/export/${name}`, encodingFormat: type || mime(name), contentSize: `${m.bytes} B`, sha256: m.sha256 });
  return {
    "@context": "https://schema.org", "@type": "Dataset", name: release.title, description, url: `${SITE_URL}/site/data.html`, sameAs: `https://doi.org/${release.doi}`, identifier: `https://doi.org/${release.doi}`, version: release.version, datePublished: release.released,
    license: "https://creativecommons.org/licenses/by/4.0/", isAccessibleForFree: true, creator, keywords, citation: `https://doi.org/${release.doi}`, isBasedOn: release.repo,
    variableMeasured: relations.map(r => ({ "@type": "PropertyValue", propertyID: r.code, name: r.title || r.code, description: `${r.records} record${r.records === 1 ? "" : "s"}, ${r.rankable} usable for ranking${r.epochs ? `, redshift ${r.epochs[0] === r.epochs[1] ? r.epochs[0] : `${r.epochs[0]} to ${r.epochs[1]}`}` : ""}`, url: r.explorer })),
    distribution: [...Object.entries(manifest.files).filter(([f]) => /\.(csv|json|bib)$/.test(f)).map(([f, m]) => dl(f, m)), { ...dl(croissant.name, croissantMeta, "application/ld+json"), description: "Croissant metadata of the CSV files" }, { ...dl("index.json", indexMeta), description: "Machine-readable index of the export files, relations and discovery files" }]
  };
}

export function siteFiles({ SITE_URL, pages, release, changelog }) {
  const urls = [`${SITE_URL}/site/index.html`, `${SITE_URL}/highline.html`, ...pages.map(p => `${SITE_URL}/site/${p}`)];
  const sitemap = `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${[...new Set(urls)].map(u => `  <url><loc>${esc(u)}</loc><lastmod>${release.released}</lastmod></url>`).join("\n")}\n</urlset>\n`;
  const robots = `User-agent: *\nAllow: /\n\nSitemap: ${SITE_URL}/sitemap.xml\n`;
  // Atom feed: one entry per released version of CHANGELOG.md ("## 0.24.0 (2026-10-18)"); the section "Unreleased" has no date and is left out
  const entries = [];
  for (const sec of changelog.split(/^## /m).slice(1)) {
    const m = sec.match(/^(\d+\.\d+\.\d+) \((\d{4}-\d{2}-\d{2})\)[^\n]*\n([\s\S]*)$/);
    if (!m) continue;
    entries.push({ version: m[1], date: m[2], bullets: m[3].split(/\n(?=- )/).map(b => b.replace(/^- /, "").replace(/\s+/g, " ").trim()).filter(Boolean) });
  }
  if (!entries.length) throw new Error("CHANGELOG.md: no released version found for the feed");
  const inline = t => esc(t).replace(/`([^`]+)`/g, "<code>$1</code>");
  const feed = `<?xml version="1.0" encoding="utf-8"?>\n<feed xmlns="http://www.w3.org/2005/Atom">\n  <title>sim-highline: releases</title>\n  <subtitle>What changed in each released version of the sim-highline dataset, from CHANGELOG.md.</subtitle>\n  <id>${esc(SITE_URL)}/feed.xml</id>\n  <link rel="self" type="application/atom+xml" href="${esc(SITE_URL)}/feed.xml"/>\n  <link rel="alternate" type="text/html" href="${esc(SITE_URL)}/site/changes.html"/>\n  <updated>${entries[0].date}T00:00:00Z</updated>\n  <author><name>${esc(release.author)}</name></author>\n`
    + entries.slice(0, 25).map(e => `  <entry>\n    <title>sim-highline ${esc(e.version)}</title>\n    <id>tag:${new URL(SITE_URL).hostname},${e.date}:sim-highline/${esc(e.version)}</id>\n    <link rel="alternate" type="text/html" href="${esc(release.repo)}/blob/main/CHANGELOG.md"/>\n    <updated>${e.date}T00:00:00Z</updated>\n    <content type="html">${esc("<ul>" + e.bullets.map(b => `<li>${inline(b)}</li>`).join("") + "</ul>")}</content>\n  </entry>`).join("\n") + "\n</feed>\n";
  return { sitemap, robots, feed, urls: [...new Set(urls)], entries };
}
